s1-armstrong-numbers.code:
bool isArmstrong(int n) {
    if (n < 0) return false;
    int digits = 0, t = n;
    do { ++digits; t /= 10; } while (t);          // count how many digits n has
    long long sum = 0;
    t = n;
    do {
        int digit = t % 10;
        long long power = 1;
        for (int i = 0; i < digits; ++i) power *= digit;  // digit raised to (digit count)
        sum += power;
        t /= 10;
    } while (t);
    return sum == n;                               // Armstrong iff that sum equals n
}

s1-check-for-prime.code:
bool isPrime(int n) {
    if (n < 2) return false;                        // 0 and 1 aren't prime
    for (int d = 2; d <= n / d; ++d)                 // only need to check up to sqrt(n)
        if (n % d == 0) return false;                // found a factor -> not prime
    return true;
}

s1-check-palindrome.code:
bool isPalindrome(int n) {
    int original = n, rev = 0;
    while (n != 0) {
        rev = rev * 10 + (n % 10);  // build the reversed number digit by digit
        n /= 10;
    }
    return original == rev;         // palindrome iff it reads the same reversed
}

s1-count-digits.code:
int countDigits(int n) {
    if (n == 0) return 1;           // 0 has exactly one digit
    int count = 0;
    while (n != 0) {
        count++;                    // one more digit found
        n /= 10;                    // strip off the last digit
    }
    return count;
}

