s1-gcd-or-hcf.code:
#include <numeric>
using namespace std;
int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;                  // key fact: gcd(a, b) == gcd(b, a % b)
        a = temp;
    }
    return a;                       // b hit 0, so a now holds the gcd
}

s1-print-all-divisors.code:
#include <algorithm>
#include <utility>
#include <vector>
using namespace std;
vector<int> divisors(int n) {
    vector<int> ans;
    if (n <= 0) return ans;
    for (int d = 1; d <= n / d; ++d) {               // check divisors up to sqrt(n)
        if (n % d == 0) {
            ans.push_back(d);
            if (d != n / d) ans.push_back(n / d);    // d's pair partner, unless d*d == n
        }
    }
    sort(ans.begin(), ans.end());
    return ans;
}

s1-reverse-a-number.code:
int reverseNumber(int n) {
    int rev = 0;
    while (n != 0) {
        int lastDigit = n % 10;     // peel off the last digit
        rev = rev * 10 + lastDigit; // shift rev left, then append the digit
        n /= 10;
    }
    return rev;
}

