#include <vector>
using namespace std;
vector<long long> factorialsUpTo(long long limit) {
    vector<long long> result;
    long long factorial = 1;
    for (long long next = 1; next <= limit / factorial; ++next) {
        factorial *= next;
        result.push_back(factorial);
    }
    return result;
}

